const iso=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
function recHTML(a,r){const [pode,why]=podeExec(a);const dis=pode?'':` dis" aria-disabled="true" data-tip="${esc(why)}`;const aberta=!recFeita(a,r);const st=aberta?'':({feita:'<span class="pill ok"><i></i>Feita</span>',recusada:'<span class="pill"><i></i>Recusada</span>'}[r.status]||'<span class="pill ok"><i></i>Criativo pedido</span>');
 return `<div class="rec ${r.status!=='aberta'?'done':''}"><div class="row" style="justify-content:space-between"><b>${esc(r.titulo)}</b>${st}</div><p class="why"><b>Por que a IA sugere isso:</b> ${esc(r.motivo)}</p>${r.impacto?`<p class="why"><b>Impacto esperado:</b> ${esc(r.impacto)}</p>`:''}${aberta&&r.aviso&&r.tipo!=='budget'?`<div class="warnb">${ic('alert')}<span>${esc(r.aviso)}</span></div>`:''}<div class="ba-g"><div><span class="lbl">Antes</span><b>${typeof r.de==='number'?brl2(r.de)+'/dia':esc(r.de)}</b></div><span>${ic('chev')}</span><div class="aft"><span class="lbl">Depois</span><b>${typeof r.para==='number'?brl2(r.para)+'/dia':esc(r.para)}</b></div></div>${r.tipo==='budget'&&aberta?invHTML(a,r.alvo,r.para):''}${aberta?`<div class="row"><button class="btn sm pri${dis}" data-act="rec-fazer" data-a="${a.id}" data-r="${r.id}">${ic(r.tipo==='criativo'?'users':'check')}${({criativo:'Pedir criativo',verificar:'Já verifiquei',aguardar:'Ciente, aguardar'})[r.tipo]||'Fazer agora'}</button>${['budget','pause','publico'].includes(r.tipo)?`<button class="btn sm${dis}" data-act="rec-ajustar" data-a="${a.id}" data-r="${r.id}">Ajustar</button>`:''}<button class="btn sm ghost${dis}" data-act="rec-recusar" data-a="${a.id}" data-r="${r.id}">Recusar</button></div>`:''}${(r.tipo==='pause'&&/anúncio/i.test(r.titulo))||r.tipo==='criativo'?`<div class="crv-rec"><span class="hint">Pausar só resolve metade: o conjunto precisa de um criativo novo.</span>${statusCrvHTML(a,'crv-st')}<div class="row">${botoesCrvHTML(a,r.alvo)}</div></div>`:''}</div>`}
